List<int>? _minCoins(List<int> coins, int amount) {
  List<int> dp = List<int>.filled(amount + 1, -1);
  List<int> coinUsed = List<int>.filled(amount + 1, -1);
  dp[0] = 0;
  for (int i = 1; i <= amount; i++) {
    for (int c in coins) {
      if (c <= i && dp[i - c] != -1) {
        int candidate = dp[i - c] + 1;
        if (dp[i] == -1 || candidate < dp[i]) {
          dp[i] = candidate;
          coinUsed[i] = c;
        }
      }
    }
  }
  if (dp[amount] == -1) return null;
  List<int> result = [];
  int cur = amount;
  while (cur > 0) {
    result.add(coinUsed[cur]);
    cur -= coinUsed[cur];
  }
  result.sort();
  return result;
}

int _countWays(List<int> coins, int amount) {
  List<int> dp = List<int>.filled(amount + 1, 0);
  dp[0] = 1;
  for (int c in coins) {
    for (int i = c; i <= amount; i++) {
      dp[i] += dp[i - c];
    }
  }
  return dp[amount];
}

